func doubleValue(_ n: Int) async -> Int {
    return n * 2
}

func run() async {
    let a = await doubleValue(5)
    let b = await doubleValue(a)
    print("Result: \(b)")
}

await run()

enum MathError: Error {
    case negative
}

func checkPositive(_ n: Int) async throws -> Int {
    if n < 0 { throw MathError.negative }
    return n
}

func calc() async {
    do {
        let val = try await checkPositive(-1)
        print("Value: \(val)")
    } catch {
        print("Caught negative error")
    }
}

await calc()

