enum AuthError: Error {
    case unverified
}

func verifyUser(token: String) async throws -> Bool {
    guard token == "valid" else { throw AuthError.unverified }
    return true
}

do {
    let ok = try await verifyUser(token: "valid")
    print("User verified: \(ok)")
} catch {
    print("Verification failed")
}

